@require_POST
def checkout(request):
    """Starts Chargebee's checkout for the card's button: "pack" or a plan id."""
    user = _user(request)
    if user is None:
        return HttpResponseRedirect(reverse('jusprin_v2_web_prices'))
    what = request.POST.get('what', '')
    back = request.build_absolute_uri(reverse('jusprin_v2_web_checkout_done'))
    if what == 'pack':
        url = billing.pack_checkout(user, back)
    elif billing.is_v2_plan(what):
        url = billing.plan_checkout(user, what, back)
    else:
        return HttpResponseRedirect(reverse('jusprin_v2_web_prices'))
    return HttpResponseRedirect(url)


@require_GET
def checkout_done(request):
    """Where Chargebee sends the person back: what was added, and Back to your
    chat, which goes to the done address."""
    user = _user(request)
    bought = billing.finish_checkout(user, request.GET['id']) if user and request.GET.get('id') else None
    if bought is None:
        return HttpResponseRedirect(reverse('jusprin_v2_web_prices'))
    now = timezone.now()
    launch = billing.launch_on(now)
    if bought['kind'] == 'pack':
        added = bought['credits'] * (2 if launch else 1)
        heading = ngettext('%(count)s credit added', '%(count)s credits added', added) % {'count': _number(added)}
        pack = {'count': _number(bought['credits'])}
        what = (ngettext('A %(count)s-credit pack, doubled for the launch.',
                         'A %(count)s-credit pack, doubled for the launch.', bought['credits']) % pack if launch
                else ngettext('A %(count)s-credit pack.', 'A %(count)s-credit pack.', bought['credits']) % pack)
    else:
        spec = settings.JUSPRIN_V2_PLANS[bought['plan_id']]
        heading = _('You’re on %(plan)s') % {'plan': spec['name']}
        what = _doubled_until(spec['credits']) if launch else _credits_a_month(spec['credits'])
        plan = active_v2_plan(user.id)
        if _yearly(bought['plan_id']) and plan is not None and plan.current_term_end:
            return render(request, 'jusprin/v2/web/purchase_done.html', {
                'title': _('Credits and plans'),
                'launch': launch,
                'heading': _('You’re on %(plan)s, paid yearly') % {'plan': spec['name']},
                'line': _yearly_bought(user, plan, spec, launch, now),
                'email': user.email,
            })
    return render(request, 'jusprin/v2/web/purchase_done.html', {
        'title': _('Credits and plans'),
        'launch': launch,
        'heading': heading,
        'line': sentences([what, _on_account(user, now)]),
        'email': user.email,
    })


        'usage': _usage_view(user, now),
