@require_http_methods(['GET', 'POST'])
def cancel(request):
    """Cancel plan: what cancelling does, then the cancel itself, which stops
    the plan at the end of the term already paid for."""
    user = _user(request)
    plan = active_v2_plan(user.id) if user else None
    if plan is None or plan.expired_at is not None:
        return HttpResponseRedirect(reverse('jusprin_v2_web_billing'))
    if request.method == 'POST':
        billing.cancel_plan(user)
        return HttpResponseRedirect(reverse('jusprin_v2_web_done'))
    spec = settings.JUSPRIN_V2_PLANS[plan.plan_id]
    keep = {'plan': spec['name'], 'date': _date(plan.current_term_end) if plan.current_term_end else ''}
    if _yearly(plan.plan_id):
        free = settings.JUSPRIN_V2_FREE_CREDITS
        lines = [(_('You keep %(plan)s until %(date)s, with new credits each month until then, and it doesn’t renew.')
                  if plan.current_term_end else
                  _('You keep %(plan)s, with new credits each month until then, and it doesn’t renew.')) % keep,
                 _('Nothing is refunded.'),
                 ngettext('After that you get the %(count)s free credit a month that accounts without a plan get.',
                          'After that you get the %(count)s free credits a month that accounts without a plan get.',
                          free) % {'count': _number(free)},
                 _('Credits from credit packs stay.')]
    else:
        lines = [(_('You keep %(plan)s and its credits until %(date)s, and it doesn’t renew.')
                  if plan.current_term_end else _('You keep %(plan)s and its credits, and it doesn’t renew.')) % keep,
                 _('Credit packs you bought stay.')]
    kept = _kept_price(plan)
    if kept is not None:
        lines.append(_('The %(price)s price isn’t offered again after it ends.') % {'price': _dollars(kept)})
    return render(request, 'jusprin/v2/web/cancel.html', {
        'title': _('Billing and usage'),
        'heading': _('Cancel %(plan)s?') % {'plan': spec['name']},
        'line': sentences(lines),
    })


@require_GET
def portal(request):
    """Chargebee's portal, for the payment method and invoices; it comes back
    to Billing and usage."""
    user = _user(request)
    if user is None or not has_paid(user.id):
        return HttpResponseRedirect(reverse('jusprin_v2_web_billing'))
    return HttpResponseRedirect(billing.portal_url(user, request.build_absolute_uri(reverse('jusprin_v2_web_billing'))))
